sp_widget.css:
/* ===============================
   COMMERCIAL WIDGET – ALL IN ONE
   =============================== */


.commercial-widget {
  background: linear-gradient(
    135deg,
    #1db954 0%,
    #ffffff 50%,
    #0b5ed7 100%
  );
  padding: 30px;
  border-radius: 14px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.12);
  height: 100%;
  position: relative;
  overflow: hidden;
  transition: transform 0.4s ease, box-shadow 0.4s ease;
}


/* Hover floating card */
.commercial-widget:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.18);
}


/* Floating animated background glow */
.commercial-widget::before {
  content: "";
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(
    circle,
    rgba(255, 255, 255, 0.25) 0%,
    transparent 60%
  );
  animation: floatBg 8s infinite linear;
  pointer-events: none;
}


/* Floating background animation */
@keyframes floatBg {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}


/* Floating heading text */
.commercial-widget h2 {
  color: #0b5ed7;
  margin-bottom: 15px;
  font-weight: 700;
  position: relative;
  animation: floatText 3s ease-in-out infinite;
}


/* Heading animation */
@keyframes floatText {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
  100% {
    transform: translateY(0);
  }
}


/* Paragraph styling */
.commercial-widget p {
  color: #222;
  font-size: 15px;
  margin-bottom: 18px;
}


/* List styling */
.commercial-widget ul {
  padding-left: 0;
  list-style: none;
}


/* Animated list items */
.commercial-widget ul li {
  padding: 10px 0;
  font-size: 14px;
  color: #222;
  opacity: 0;
  animation: slideIn 0.8s ease forwards;
}


/* Staggered animation */
.commercial-widget ul li:nth-child(1) { animation-delay: 0.2s; }
.commercial-widget ul li:nth-child(2) { animation-delay: 0.4s; }
.commercial-widget ul li:nth-child(3) { animation-delay: 0.6s; }
.commercial-widget ul li:nth-child(4) { animation-delay: 0.8s; }


/* Slide-in effect */
@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateX(-15px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}


/* ===============================
   OPTIONAL CROSS-WIDGET EFFECT
   (Both widgets in same row)
   =============================== */


.row:hover .commercial-widget,
.row:hover .raise-ticket-widget {
  transform: translateY(-5px) scale(1.01);
} .
